import { Component, OnInit } from '@angular/core';
import { DestinationService } from '../../../services/destination.service';
import { WishlistService } from '../../../services/wishlist.service';
import { Destination, PaginatedDestinationResponse } from '../../../models/destination.model';
import { AuthService } from '../../../services/auth.service';

@Component({
    selector: 'app-destinations-list',
    templateUrl: './destinations-list.component.html',
    styleUrls: ['./destinations-list.component.css']
})
export class DestinationsListComponent implements OnInit {
    destinations: Destination[] = [];
    page = 0;
    size = 10;
    totalElements = 0;
    totalPages = 0;
    loading = false;
    searchQuery = '';
    isAdmin = false;

    // Wishlist Management
    wishlistIds: Set<number> = new Set();
    toastMessage: string | null = null;
    toastType: 'success' | 'error' = 'success';

    constructor(
        private destinationService: DestinationService,
        private wishlistService: WishlistService,
        private authService: AuthService
    ) { }

    ngOnInit(): void {
        this.checkAdmin();
        this.loadDestinations();
        this.loadWishlistIds(); // Load user favorites
    }

    checkAdmin() {
        const user = this.authService.currentUserValue;
        this.isAdmin = user?.role === 'ADMIN' || user?.username === 'kareem';
    }

    deleteDestination(id?: number) {
        if (!id) return;
        if (!confirm('Are you sure you want to delete this destination? This action cannot be undone.')) return;

        this.destinationService.deleteDestination(id).subscribe({
            next: () => {
                this.showToast('Destination deleted successfully!', 'success');
                this.destinations = this.destinations.filter(d => d.id !== id);
            },
            error: (e) => {
                console.error(e);
                this.showToast('Failed to delete destination.', 'error');
            }
        });
    }

    loadDestinations() {
        this.loading = true;
        this.destinationService.getAllDestinations(this.page, this.size)
            .subscribe({
                next: (response) => {
                    this.destinations = response.data.content;
                    this.totalElements = response.data.totalElements;
                    this.totalPages = response.data.totalPages;
                    this.loading = false;
                },
                error: (e) => {
                    console.error(e);
                    this.loading = false;
                }
            });
    }

    loadWishlistIds() {
        // Only load if user is logged in (not admin specifically, any user)
        if (this.authService.isAuthenticated()) {
            this.wishlistService.getWishlist().subscribe({
                next: (response) => {
                    // Create a Set of IDs for O(1) lookup
                    if (response.data) {
                        this.wishlistIds = new Set(response.data.map(d => d.id).filter((id): id is number => !!id));
                    }
                },
                error: (e) => console.error('Failed to load wishlist status', e)
            });
        }
    }

    // New smart toggle method
    toggleWishlist(destination: Destination) {
        if (!destination.id) return;
        const id = destination.id;

        if (this.wishlistIds.has(id)) {
            // Already in wishlist -> Remove it
            this.wishlistService.removeFromWishlist(id).subscribe({
                next: () => {
                    this.wishlistIds.delete(id);
                    this.showToast(`${destination.country} removed from your wishlist`, 'success');
                },
                error: () => this.showToast('Failed to remove from wishlist', 'error')
            });
        } else {
            // Not in wishlist -> Add it
            this.wishlistService.addToWishlist(id).subscribe({
                next: () => {
                    this.wishlistIds.add(id);
                    this.showToast(`${destination.country} added to your wishlist! ❤️`, 'success');
                },
                error: () => this.showToast('Failed to add to wishlist', 'error')
            });
        }
    }

    // Check helper for UI
    isInWishlist(id?: number): boolean {
        return !!id && this.wishlistIds.has(id);
    }

    // Custom Toast Notification Logic
    showToast(message: string, type: 'success' | 'error') {
        this.toastMessage = message;
        this.toastType = type;
        setTimeout(() => {
            this.toastMessage = null;
        }, 3000); // Hide after 3 seconds
    }

    onPageChange(event: any) {
        this.page = event.pageIndex;
        this.size = event.pageSize;
        this.loadDestinations();
    }

    onSearch() {
        this.page = 0;
        this.totalPages = 0;
        this.totalElements = 0;

        if (this.searchQuery.trim()) {
            this.loading = true;
            this.destinationService.searchDestinations(this.searchQuery)
                .subscribe({
                    next: (response) => {
                        this.destinations = response.data;
                        this.totalElements = response.data.length;
                        this.totalPages = 1;
                        this.loading = false;
                    },
                    error: (e) => {
                        console.error(e);
                        this.loading = false;
                    }
                });
        } else {
            this.loadDestinations();
        }
    }

    // Deprecated but kept to avoid strict template errors if referenced
    addToWishlist(destination: Destination) {
        this.toggleWishlist(destination);
    }
}
